add_rewrite_endpoint( 'wpbp-reviews', EP_PERMALINK );
add_filter(
    'request',
    static function ( array $query_vars ): array {
        if ( array_key_exists( 'wpbp-reviews', $query_vars ) && '' === $query_vars['wpbp-reviews'] ) {
            $query_vars['wpbp-reviews'] = 'all';
        }
        return $query_vars;
    }
);

function wpbp_rewrite_permalinks_005(): void {
    register_post_type(
        'wpbp_guide',
        array(
            'label'        => 'WPBP Guides',
            'public'       => true,
            'has_archive'  => false,
            'supports'     => array( 'title', 'editor' ),
            'rewrite'      => array(
                'slug'       => 'guides',
                'with_front' => false,
            ),
        )
    );
}

function wpbp_rewrite_permalinks_006(): void {
    add_filter(
        'rewrite_rules_array',
        static function ( array $rules ): array {
            $custom   = array( 'wpbp-archive/?$' => 'index.php?wpbp_archive=1' );
            $merged   = array();
            $inserted = false;
            foreach ( $rules as $regex => $query ) {
                if ( ! $inserted && 1 === preg_match( '#^' . $regex . '#', 'wpbp-archive/' ) ) {
                    $merged   = array_merge( $merged, $custom );
                    $inserted = true;
                }
                $merged[ $regex ] = $query;
            }
            if ( ! $inserted ) {
                $merged = array_merge( $merged, $custom );
            }
            return $merged;
        }
    );
    add_filter(
        'query_vars',
        static function ( array $vars ): array {
            $vars[] = 'wpbp_archive';
            return $vars;
        }
    );
}
